(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.016-t*0.22)*18 + Math.sin(x*0.015+t*0.3)*12;
  const w2x = Math.sin((x+w1x)*0.012-t*0.15)*8;
  const w2y = Math.cos((y+w1y)*0.011+t*0.2)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.075, 2.0, 0.8],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7, 0.6],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.0],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 0.9],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.085, 1.9, 0.7],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.45+2)*60, 0.1, 2.1, 0.4],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.65+4)*50, 0.07, 1.8, 0.85]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    const ring = Math.cos(d*f*0.3+t*sp*0.4)*0.5;
    aS += wave*w;
    iS += Math.sin(d*f*0.6+t*sp*0.5+1.5)*w;
    cS += (wave+ring)*w*0.3;
  }
  aS/=8; iS/=8; cS/=8;
  const bg1 = Math.sin(sx*0.035+sy*0.022+t*0.7);
  const bg2 = Math.sin(sx*0.028-sy*0.035+t*0.95);
  const bg3 = Math.sin((sx+sy)*0.1+t*2.2)*0.25;
  const bg4 = Math.sin((sx-sy)*0.08-t*1.8)*0.25;
  const bg = (bg1+bg2)/2+bg3+bg4;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2 = Math.sin(dist*0.035+ang*5-t*1.0);
  const sp3 = Math.sin(dist*0.06-ang*2+ang*ang*0.005-t*0.8)*0.5;
  const spiral = (sp1+sp2)*0.3+sp3;
  const vx = (sx*0.13)|0, vy = (sy*0.13)|0;
  const vorX = vx+Math.sin(vx*1.1+vy*0.7+t*0.3)*0.5;
  const vorY = vy+Math.cos(vx*0.8+vy*1.2-t*0.25)*0.5;
  const cell = Math.sin(vorX*3.7+vorY*2.3)*Math.cos(vorX*2.1-vorY*3.1+t*0.4);
  const rd1 = Math.tanh((aS - iS*0.65 + bg*0.25 + spiral*0.35)*2.0);
  const rd2 = Math.tanh((cS + iS*0.3 + cell*0.4 + spiral*-0.2)*1.8);
  const coupling = Math.tanh((rd1*0.7+rd2*0.3+cell*0.15)*1.6);
  const lum = 0.75+Math.sin(coupling*Math.PI*1.2)*0.25;
  const edge = 1.0+(Math.abs(coupling)>0.6?0.2:0)+(Math.abs(rd1-rd2)>0.3?0.1:0);
  const pal = [
    [5,12,52],[10,35,85],[12,65,110],[18,110,120],
    [45,155,130],[120,185,105],[190,195,70],
    [220,175,65],[215,130,60],[185,80,55],
    [140,45,60],[85,25,55],[40,15,48],[5,12,52]
  ];
  const v = coupling*0.5+0.5;
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0
  ];
}
